CREATE OR REPLACE FUNCTION trip_private.can_view_culture(p_exp uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.culture_experiences e WHERE e.id=p_exp AND (CASE WHEN e.a2e_kind IS NOT NULL THEN trip_private.a2e_culture_access(e.id) ELSE e.creator_id=auth.uid() OR trip_private.is_app_admin() OR (e.visibility='squad' AND e.trip_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=e.trip_id AND m.user_id=auth.uid() AND m.status='approved')) OR (e.visibility='public' AND e.finished_at IS NOT NULL AND e.unlisted_at IS NULL AND trip_private.has_beta_access()) END)) $$;
REVOKE ALL ON FUNCTION trip_private.can_view_culture(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.can_view_culture(uuid) TO authenticated,service_role;
DO $migration$ DECLARE def text; BEGIN SELECT pg_get_functiondef('trip_private.culture_showcase(text,uuid,text,jsonb)'::regprocedure) INTO def; def:=replace(def, 'least(v_at+interval ''1 day'',now()+interval ''30 days'')', 'v_at+interval ''1 day'''); EXECUTE def; END $migration$;